export function* walkTree(root,{prune=()=>false}={}){
 if(root===null)return;const frames=[{items:[root],index:0}];
 while(frames.length){const frame=frames.at(-1);if(frame.index===frame.items.length){frames.pop();continue;}const node=frame.items[frame.index++];yield node;if(!prune(node)){const children=node.children??[];if(children.length)frames.push({items:children,index:0});}}
}

